CREATE COLUMN TABLE "TEST_AP"."AUNCL" ("AbsEntry" INTEGER CS_INT NOT NULL , "Codelist" INTEGER CS_INT, "Code" NVARCHAR(20), "Descrip" NVARCHAR(254), "SchemaCode" NVARCHAR(20) DEFAULT ' ', "SchemaDesc" NVARCHAR(254), "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "UpdateDate" LONGDATE CS_LONGDATE, "UserSign" SMALLINT CS_INT, "UserSign2" SMALLINT CS_INT, "IsDefault" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("AbsEntry", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "AUNCL_IsDefault" ON "TEST_AP"."AUNCL" ( "IsDefault" ASC )